select B.MSG_ID, B.SITE_ID, B.ORGAN_ID, B.BIZ_TYPE, B.TYPE, B.TITLE, B.CONTENT, B.MSG_URL, B.FOREIGN_ID, B.IMAGE_PATH, B.ICON_STYLE, B.RECV_MEMBER_ID, B.RECV_GROUP_ID, B.RECV_ORGAN_ID, B.RECV_TARGETID, B.STATUS, B.CREATE_TIME, B.CREATOR_ID, B.UPDATOR_ID, B.UPDATE_TIME, B.LAST_TIME, B.DESCRIPTION , B.readStatus from ( SELECT B.MSG_ID, B.SITE_ID, B.ORGAN_ID, B.BIZ_TYPE, B.TYPE, B.TITLE, B.CONTENT, B.MSG_URL, B.FOREIGN_ID, B.IMAGE_PATH, B.ICON_STYLE, B.RECV_MEMBER_ID, B.RECV_GROUP_ID, B.RECV_ORGAN_ID, B.RECV_TARGETID, B.STATUS, B.CREATE_TIME, B.CREATOR_ID, B.UPDATOR_ID, B.UPDATE_TIME, B.LAST_TIME, B.DESCRIPTION, (case when (( EXISTS (SELECT A.RECORD_ID FROM PORTAL_UNION_MESSAGE A WHERE A.TYPE='PUBLIC_NOTICE' AND A.MSG_USER_ID =#{recvMemberId} AND A.MSG_ID = B.MSG_ID ))) then 1 else 0 end) as readStatus FROM PUBLIC_NOTICE B WHERE 1=1
